"""The ontology starters' terms, with the IRIs SPARQL uses for them.

Generated by database/scripts/gen-starter-terms.mjs from
database/crates/lbb-ontology/starters/<id>.json. Do not edit: run
database/scripts/gen-clients.sh.

Usage: ``from lbb.starters import crm``, then ``crm.classes.Organization.iri``.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class StarterClass:
    """A class of a starter. ``super_types`` are its direct parents, by name."""

    name: str
    iri: str
    super_types: tuple[str, ...]


@dataclass(frozen=True)
class StarterProperty:
    """A property of a starter. Properties are global: one value type each."""

    name: str
    iri: str
    value_type: str


@dataclass(frozen=True)
class StarterRelation:
    """A relation of a starter. ``inverse`` names the reverse direction."""

    name: str
    iri: str
    domain: tuple[str, ...]
    range: tuple[str, ...]
    cardinality: str
    inverse: str | None
    inverse_iri: str | None


@dataclass(frozen=True)
class StarterQuestion:
    """A question the starter's ontology answers, with its SPARQL when one exists."""

    id: str
    text: str
    sparql: str | None


