class _Crm:
    """The CRM starter 1.0.0."""

    id = "crm"
    version = "1.0.0"
    label = "CRM"
    classes = _CrmClasses
    properties = _CrmProperties
    relations = _CrmRelations
    questions: tuple[StarterQuestion, ...] = (
        StarterQuestion(id="crm-01", text="Which organizations does a person work at, and with what job title?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?person ?organization ?job_title WHERE {\n  # Input: a person's name. UNDEF answers for every person.\n  VALUES ?person { UNDEF }\n  ?x a/rdfs:subClassOf* c:person ;\n     rdfs:label ?person ;\n     r:works_at ?o .\n  ?o a/rdfs:subClassOf* c:organization ;\n     rdfs:label ?organization .\n  OPTIONAL { ?x p:job_title ?job_title }\n}\nORDER BY ?person ?organization\n"),
        StarterQuestion(id="crm-02", text="Which deals are open for an organization, with their amount and stage?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?organization ?deal ?amount ?currency ?stage WHERE {\n  # Input: an organization's name. UNDEF answers for every organization.\n  VALUES ?organization { UNDEF }\n  ?o a/rdfs:subClassOf* c:organization ;\n     rdfs:label ?organization .\n  ?d a/rdfs:subClassOf* c:deal ;\n     r:for_organization ?o ;\n     p:is_closed false ;\n     rdfs:label ?deal .\n  OPTIONAL { ?d p:amount ?amount }\n  OPTIONAL { ?d p:currency ?currency }\n  OPTIONAL { ?d r:in_stage ?s . ?s a/rdfs:subClassOf* c:stage ; rdfs:label ?stage }\n}\nORDER BY ?organization DESC(?amount)\n"),
        StarterQuestion(id="crm-03", text="What is the open pipeline amount per pipeline and stage, in stage order?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?pipeline ?stage ?currency (COUNT(?d) AS ?deals) (SUM(?amount) AS ?open_amount) WHERE {\n  ?d a/rdfs:subClassOf* c:deal ;\n     p:is_closed false ;\n     p:amount ?amount ;\n     r:in_stage ?s .\n  OPTIONAL { ?d p:currency ?currency }\n  ?s a/rdfs:subClassOf* c:stage ;\n     rdfs:label ?stage ;\n     p:display_order ?order ;\n     r:in_pipeline ?pl .\n  ?pl a/rdfs:subClassOf* c:pipeline ;\n      rdfs:label ?pipeline .\n}\nGROUP BY ?pipeline ?stage ?order ?currency\nORDER BY ?pipeline ?order ?currency\n"),
        StarterQuestion(id="crm-04", text="Which deals are expected to close this quarter, and who owns them?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?deal ?close_date ?amount ?currency ?owner WHERE {\n  ?d a/rdfs:subClassOf* c:deal ;\n     rdfs:label ?deal ;\n     p:is_closed false ;\n     p:close_date ?close_date .\n  # This quarter: the year and the quarter of today.\n  FILTER(YEAR(?close_date) = YEAR(NOW())\n         && CEIL(MONTH(?close_date) / 3) = CEIL(MONTH(NOW()) / 3))\n  OPTIONAL { ?d p:amount ?amount }\n  OPTIONAL { ?d p:currency ?currency }\n  OPTIONAL { ?d r:owned_by ?u . ?u a/rdfs:subClassOf* c:user ; rdfs:label ?owner }\n}\nORDER BY ?close_date\n"),
        StarterQuestion(id="crm-05", text="Which deals were won or lost in a period, and why were the lost ones lost?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n\nSELECT ?deal ?close_date ?won ?lost_reason WHERE {\n  # Inputs: the period's first instant and the instant after it, as\n  # xsd:dateTime. UNDEF leaves that end open.\n  VALUES (?from ?to) { (UNDEF UNDEF) }\n  ?d a/rdfs:subClassOf* c:deal ;\n     rdfs:label ?deal ;\n     p:is_closed true ;\n     p:is_won ?won ;\n     p:close_date ?close_date .\n  FILTER(!BOUND(?from) || ?close_date >= ?from)\n  FILTER(!BOUND(?to) || ?close_date < ?to)\n  OPTIONAL { ?d p:lost_reason ?lost_reason }\n}\nORDER BY ?close_date\n"),
        StarterQuestion(id="crm-06", text="Who are the people involved in a deal, and what are their job titles?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?deal ?person ?job_title WHERE {\n  # Input: a deal's name. UNDEF answers for every deal.\n  VALUES ?deal { UNDEF }\n  ?d a/rdfs:subClassOf* c:deal ;\n     rdfs:label ?deal ;\n     r:involves ?x .\n  ?x a/rdfs:subClassOf* c:person ;\n     rdfs:label ?person .\n  OPTIONAL { ?x p:job_title ?job_title }\n}\nORDER BY ?deal ?person\n"),
        StarterQuestion(id="crm-07", text="What calls, emails and meetings happened with an organization in the last 30 days?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n\nSELECT ?organization ?activity ?kind ?occurred_at WHERE {\n  # Inputs: an organization's name, and the start of the window (30 days\n  # ago) as xsd:dateTime. UNDEF answers for every organization or date.\n  VALUES (?organization ?since) { (UNDEF UNDEF) }\n  ?o a/rdfs:subClassOf* c:organization ;\n     rdfs:label ?organization .\n  ?a a/rdfs:subClassOf* c:activity ;\n     r:about ?o ;\n     rdfs:label ?activity ;\n     p:occurred_at ?occurred_at ;\n     a ?type .\n  VALUES (?type ?kind) { (c:call \"call\") (c:email \"email\") (c:meeting \"meeting\") }\n  FILTER(!BOUND(?since) || ?occurred_at >= ?since)\n  FILTER(?occurred_at <= NOW())\n}\nORDER BY ?organization DESC(?occurred_at)\n"),
        StarterQuestion(id="crm-08", text="When was the last activity with a person, and what kind was it?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?person ?activity ?kind ?occurred_at WHERE {\n  # Input: a person's name. UNDEF answers for every person.\n  VALUES ?person { UNDEF }\n  ?x a/rdfs:subClassOf* c:person ;\n     rdfs:label ?person .\n  {\n    SELECT ?x (MAX(?at) AS ?occurred_at) WHERE {\n      ?any a/rdfs:subClassOf* c:activity ;\n           r:about ?x ;\n           p:occurred_at ?at .\n      FILTER(?at <= NOW())\n    }\n    GROUP BY ?x\n  }\n  ?a a/rdfs:subClassOf* c:activity ;\n     r:about ?x ;\n     p:occurred_at ?occurred_at ;\n     rdfs:label ?activity ;\n     a ?type .\n  ?type rdfs:subClassOf+ c:activity .\n  BIND(STRAFTER(STR(?type), \"/class/\") AS ?kind)\n}\nORDER BY ?person\n"),
        StarterQuestion(id="crm-09", text="Which open tickets does an organization have, by priority and stage?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?organization ?ticket ?priority ?stage WHERE {\n  # Input: an organization's name. UNDEF answers for every organization.\n  VALUES ?organization { UNDEF }\n  ?o a/rdfs:subClassOf* c:organization ;\n     rdfs:label ?organization .\n  ?t a/rdfs:subClassOf* c:ticket ;\n     r:for_organization ?o ;\n     p:is_closed false ;\n     rdfs:label ?ticket .\n  OPTIONAL { ?t p:priority ?priority }\n  OPTIONAL { ?t r:in_stage ?s . ?s a/rdfs:subClassOf* c:stage ; rdfs:label ?stage }\n}\nORDER BY ?organization ?priority ?stage\n"),
        StarterQuestion(id="crm-10", text="Which users own the most open deals and tickets?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?owner (COUNT(?record) AS ?open_records) WHERE {\n  { ?record a/rdfs:subClassOf* c:deal } UNION { ?record a/rdfs:subClassOf* c:ticket }\n  ?record p:is_closed false ;\n          r:owned_by ?u .\n  ?u a/rdfs:subClassOf* c:user ;\n     rdfs:label ?owner .\n}\nGROUP BY ?owner\nORDER BY DESC(?open_records) ?owner\n"),
        StarterQuestion(id="crm-11", text="Which teams does a user belong to, and is the user active?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?user ?is_active ?team WHERE {\n  # Input: a user's name. UNDEF answers for every user.\n  VALUES ?user { UNDEF }\n  ?u a/rdfs:subClassOf* c:user ;\n     rdfs:label ?user .\n  OPTIONAL { ?u p:is_active ?is_active }\n  OPTIONAL { ?u r:member_of ?t . ?t a/rdfs:subClassOf* c:team ; rdfs:label ?team }\n}\nORDER BY ?user ?team\n"),
        StarterQuestion(id="crm-12", text="Which products does a deal sell, with quantity and price?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?deal ?product ?sku ?quantity ?unit_price ?amount WHERE {\n  # Input: a deal's name. UNDEF answers for every deal.\n  VALUES ?deal { UNDEF }\n  ?d a/rdfs:subClassOf* c:deal ;\n     rdfs:label ?deal ;\n     r:has_line_item ?line .\n  ?line a/rdfs:subClassOf* c:lineitem .\n  OPTIONAL { ?line p:quantity ?quantity }\n  OPTIONAL { ?line p:unit_price ?unit_price }\n  OPTIONAL { ?line p:amount ?amount }\n  OPTIONAL {\n    ?line r:for_product ?pr .\n    ?pr a/rdfs:subClassOf* c:product ;\n        rdfs:label ?product .\n    OPTIONAL { ?pr p:sku ?sku }\n  }\n}\nORDER BY ?deal ?product\n"),
        StarterQuestion(id="crm-13", text="Which quotes exist for a deal, and when do they expire?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?deal ?quote ?status ?amount ?currency ?expires_at WHERE {\n  # Input: a deal's name. UNDEF answers for every deal.\n  VALUES ?deal { UNDEF }\n  ?d a/rdfs:subClassOf* c:deal ;\n     rdfs:label ?deal .\n  ?q a/rdfs:subClassOf* c:quote ;\n     r:quote_for ?d ;\n     rdfs:label ?quote .\n  OPTIONAL { ?q p:status ?status }\n  OPTIONAL { ?q p:amount ?amount }\n  OPTIONAL { ?q p:currency ?currency }\n  OPTIONAL { ?q p:expires_at ?expires_at }\n}\nORDER BY ?deal ?expires_at\n"),
        StarterQuestion(id="crm-14", text="Which organizations belong to a parent organization, directly or indirectly?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?parent ?organization ?domain ?direct_parent WHERE {\n  # Input: the parent organization's name. UNDEF answers for every parent.\n  VALUES ?parent { UNDEF }\n  ?top a/rdfs:subClassOf* c:organization ;\n       rdfs:label ?parent .\n  # Directly or indirectly: one or more SUBSIDIARY_OF steps.\n  ?o r:subsidiary_of+ ?top ;\n     rdfs:label ?organization ;\n     r:subsidiary_of ?up .\n  ?up rdfs:label ?direct_parent .\n  OPTIONAL { ?o p:domain ?domain }\n}\nORDER BY ?parent ?organization\n"),
        StarterQuestion(id="crm-15", text="Which leads came from a campaign, and which of them converted to deals?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?campaign ?campaign_start ?lead ?lead_source ?converted_deal WHERE {\n  # Input: a campaign's name. UNDEF answers for every campaign.\n  VALUES ?campaign { UNDEF }\n  ?k a/rdfs:subClassOf* c:campaign ;\n     rdfs:label ?campaign .\n  OPTIONAL { ?k p:start_at ?campaign_start }\n  ?l a/rdfs:subClassOf* c:lead ;\n     r:in_campaign ?k ;\n     rdfs:label ?lead .\n  OPTIONAL { ?l p:lead_source ?lead_source }\n  OPTIONAL {\n    ?l r:converted_to ?d .\n    ?d a/rdfs:subClassOf* c:deal ;\n       rdfs:label ?converted_deal .\n  }\n}\nORDER BY ?campaign ?lead\n"),
        StarterQuestion(id="crm-16", text="Who reports to a given person?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?manager ?person ?job_title WHERE {\n  # Input: the manager's name. UNDEF answers for every manager.\n  VALUES ?manager { UNDEF }\n  ?m a/rdfs:subClassOf* c:person ;\n     rdfs:label ?manager .\n  ?x r:reports_to ?m ;\n     rdfs:label ?person .\n  OPTIONAL { ?x p:job_title ?job_title }\n}\nORDER BY ?manager ?person\n"),
        StarterQuestion(id="crm-17", text="Which organizations are in an industry and country, with their size and revenue?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?organization ?industry ?country ?employee_count ?annual_revenue WHERE {\n  # Inputs: an industry and a country. UNDEF answers for every industry or\n  # country.\n  VALUES (?industry ?country) { (UNDEF UNDEF) }\n  ?o a/rdfs:subClassOf* c:organization ;\n     rdfs:label ?organization ;\n     p:industry ?industry ;\n     p:country ?country .\n  OPTIONAL { ?o p:employee_count ?employee_count }\n  OPTIONAL { ?o p:annual_revenue ?annual_revenue }\n}\nORDER BY DESC(?annual_revenue)\n"),
        StarterQuestion(id="crm-18", text="What lifecycle stage and lead status does an organization or person have?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?party ?kind ?lifecycle_stage ?lead_status WHERE {\n  # Input: the name of an organization or a person. UNDEF answers for every\n  # one.\n  VALUES ?party { UNDEF }\n  ?x a/rdfs:subClassOf* c:party ;\n     rdfs:label ?party .\n  { ?x a/rdfs:subClassOf* c:organization BIND(\"organization\" AS ?kind) }\n  UNION\n  { ?x a/rdfs:subClassOf* c:person BIND(\"person\" AS ?kind) }\n  OPTIONAL { ?x p:lifecycle_stage ?lifecycle_stage }\n  OPTIONAL { ?x p:lead_status ?lead_status }\n}\nORDER BY ?kind ?party\n"),
        StarterQuestion(id="crm-19", text="Which open deals have had no activity in 30 days?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n\nSELECT ?deal ?owner WHERE {\n  # Input: the start of the window (30 days ago) as xsd:dateTime. UNDEF\n  # finds the open deals with no activity at all.\n  VALUES ?since { UNDEF }\n  ?d a/rdfs:subClassOf* c:deal ;\n     rdfs:label ?deal ;\n     p:is_closed false .\n  FILTER NOT EXISTS {\n    ?a a/rdfs:subClassOf* c:activity ;\n       r:about ?d ;\n       p:occurred_at ?at .\n    FILTER(!BOUND(?since) || ?at >= ?since)\n  }\n  OPTIONAL { ?d r:owned_by ?u . ?u rdfs:label ?owner }\n}\nORDER BY ?deal\n"),
        StarterQuestion(id="crm-20", text="Which tasks are overdue, on which records, and who does them?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?task ?status ?due_at ?record ?assignee WHERE {\n  ?t a/rdfs:subClassOf* c:task ;\n     rdfs:label ?task ;\n     p:due_at ?due_at .\n  # Overdue: due before now and not done.\n  FILTER(?due_at < NOW())\n  FILTER NOT EXISTS { ?t p:completed_at ?completed_at }\n  OPTIONAL { ?t p:status ?status }\n  OPTIONAL { ?t r:about ?x . ?x rdfs:label ?record }\n  OPTIONAL { ?t r:assigned_to ?u . ?u rdfs:label ?assignee }\n}\nORDER BY ?due_at\n"),
        StarterQuestion(id="crm-21", text="Which meetings are set for next week, and with whom?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n\nSELECT ?meeting ?start_at ?end_at ?location ?person WHERE {\n  # Inputs: the window's first instant and the instant after it, as\n  # xsd:dateTime (next Monday and the Monday after). UNDEF reads from now on.\n  VALUES (?from ?to) { (UNDEF UNDEF) }\n  ?m a/rdfs:subClassOf* c:meeting ;\n     rdfs:label ?meeting ;\n     p:start_at ?start_at .\n  FILTER(?start_at >= COALESCE(?from, NOW()))\n  FILTER(!BOUND(?to) || ?start_at < ?to)\n  OPTIONAL { ?m p:end_at ?end_at }\n  OPTIONAL { ?m p:location ?location }\n  OPTIONAL { ?m r:about ?x . ?x a/rdfs:subClassOf* c:person ; rdfs:label ?person }\n}\nORDER BY ?start_at ?person\n"),
        StarterQuestion(id="crm-22", text="What is each owner's win rate: won deals out of closed deals?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?owner (SUM(IF(?won, 1, 0)) AS ?won_deals) (COUNT(?d) AS ?closed_deals)\n       (SUM(IF(?won, 1, 0)) / COUNT(?d) AS ?win_rate) WHERE {\n  ?d a/rdfs:subClassOf* c:deal ;\n     p:is_closed true ;\n     p:is_won ?won ;\n     r:owned_by ?u .\n  ?u a/rdfs:subClassOf* c:user ;\n     rdfs:label ?owner .\n}\nGROUP BY ?owner\nORDER BY DESC(?win_rate) ?owner\n"),
        StarterQuestion(id="crm-23", text="Which tickets involve a person, and through which channel did they come in?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?person ?ticket ?channel ?created_at WHERE {\n  # Input: a person's name. UNDEF answers for every person.\n  VALUES ?person { UNDEF }\n  ?x a/rdfs:subClassOf* c:person ;\n     rdfs:label ?person .\n  ?t a/rdfs:subClassOf* c:ticket ;\n     r:involves ?x ;\n     rdfs:label ?ticket .\n  OPTIONAL { ?t p:channel ?channel }\n  OPTIONAL { ?t p:created_at ?created_at }\n}\nORDER BY ?person ?created_at\n"),
        StarterQuestion(id="crm-24", text="Which organizations have both open tickets and open deals?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?organization WHERE {\n  ?o a/rdfs:subClassOf* c:organization ;\n     rdfs:label ?organization .\n  FILTER EXISTS {\n    ?t a/rdfs:subClassOf* c:ticket ; r:for_organization ?o ; p:is_closed false .\n  }\n  FILTER EXISTS {\n    ?d a/rdfs:subClassOf* c:deal ; r:for_organization ?o ; p:is_closed false .\n  }\n}\nORDER BY ?organization\n"),
        StarterQuestion(id="crm-25", text="Where does a record come from: which system, which id, which link?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?record ?kind ?source_system ?source_id ?source_url ?source_updated_at WHERE {\n  # Input: a record's name. UNDEF answers for every organization and person.\n  VALUES ?record { UNDEF }\n  { ?x a/rdfs:subClassOf* c:organization BIND(\"organization\" AS ?kind) }\n  UNION\n  { ?x a/rdfs:subClassOf* c:person BIND(\"person\" AS ?kind) }\n  ?x rdfs:label ?record ;\n     p:source_system ?source_system .\n  OPTIONAL { ?x p:source_id ?source_id }\n  OPTIONAL { ?x p:source_url ?source_url }\n  OPTIONAL { ?x p:source_updated_at ?source_updated_at }\n}\nORDER BY ?kind ?record\n"),
        StarterQuestion(id="crm-26", text="Which notes were written on a deal, and when?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?deal ?note ?created_at ?text WHERE {\n  # Input: a deal's name. UNDEF answers for every deal.\n  VALUES ?deal { UNDEF }\n  ?d a/rdfs:subClassOf* c:deal ;\n     rdfs:label ?deal .\n  ?n a/rdfs:subClassOf* c:note ;\n     r:about ?d ;\n     rdfs:label ?note .\n  OPTIONAL { ?n p:created_at ?created_at }\n  OPTIONAL { ?n p:text ?text }\n}\nORDER BY ?deal DESC(?created_at)\n"),
        StarterQuestion(id="crm-27", text="How many calls did each user make, with what outcomes and how long?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?user ?direction ?outcome (COUNT(?call) AS ?calls) (SUM(?seconds) AS ?total_seconds) WHERE {\n  ?call a/rdfs:subClassOf* c:call ;\n        r:owned_by ?u .\n  ?u a/rdfs:subClassOf* c:user ;\n     rdfs:label ?user .\n  OPTIONAL { ?call p:direction ?direction }\n  OPTIONAL { ?call p:outcome ?outcome }\n  OPTIONAL { ?call p:duration_seconds ?seconds }\n}\nGROUP BY ?user ?direction ?outcome\nORDER BY ?user ?direction ?outcome\n"),
        StarterQuestion(id="crm-28", text="Which emails were exchanged with a person?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?person ?email ?from_address ?to_address ?occurred_at WHERE {\n  # Input: a person's name. UNDEF answers for every person.\n  VALUES ?person { UNDEF }\n  ?x a/rdfs:subClassOf* c:person ;\n     rdfs:label ?person .\n  ?m a/rdfs:subClassOf* c:email ;\n     r:about ?x ;\n     rdfs:label ?email .\n  OPTIONAL { ?m p:from_address ?from_address }\n  OPTIONAL { ?m p:to_addresses ?to_address }\n  OPTIONAL { ?m p:occurred_at ?occurred_at }\n}\nORDER BY ?person DESC(?occurred_at)\n"),
        StarterQuestion(id="crm-29", text="Which campaigns are running, with their budget and members?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?campaign ?status ?start_at ?end_at ?budget ?member WHERE {\n  ?k a/rdfs:subClassOf* c:campaign ;\n     rdfs:label ?campaign ;\n     p:start_at ?start_at ;\n     p:end_at ?end_at .\n  # Running: started and not ended.\n  FILTER(?start_at <= NOW() && ?end_at >= NOW())\n  OPTIONAL { ?k p:status ?status }\n  OPTIONAL { ?k p:budget ?budget }\n  OPTIONAL {\n    ?m r:in_campaign ?k ;\n       a/rdfs:subClassOf* c:person ;\n       rdfs:label ?member .\n  }\n}\nORDER BY ?campaign ?member\n"),
        StarterQuestion(id="crm-30", text="What does the product catalog sell, and at what price?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?product ?sku ?unit_price ?currency WHERE {\n  ?x a/rdfs:subClassOf* c:product ;\n     rdfs:label ?product ;\n     p:is_active true .\n  OPTIONAL { ?x p:sku ?sku }\n  OPTIONAL { ?x p:unit_price ?unit_price }\n  OPTIONAL { ?x p:currency ?currency }\n}\nORDER BY ?product\n"),
    )


crm = _Crm()


