class _Documents:
    """The Documents starter 1.0.0."""

    id = "documents"
    version = "1.0.0"
    label = "Documents"
    classes = _DocumentsClasses
    properties = _DocumentsProperties
    relations = _DocumentsRelations
    questions: tuple[StarterQuestion, ...] = (
        StarterQuestion(id="doc-01", text="Which documents are in a folder, and how big are they?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?folder ?document ?size_bytes ?file_extension WHERE {\n  # Input: a folder's name. UNDEF answers for every folder.\n  VALUES ?folder { UNDEF }\n  ?f a/rdfs:subClassOf* c:folder ;\n     rdfs:label ?folder .\n  ?d a/rdfs:subClassOf* c:document ;\n     r:in_folder ?f ;\n     rdfs:label ?document .\n  OPTIONAL { ?d p:size_bytes ?size_bytes }\n  OPTIONAL { ?d p:file_extension ?file_extension }\n}\nORDER BY ?folder DESC(?size_bytes)\n"),
        StarterQuestion(id="doc-02", text="Which documents in a library changed last week, and who changed them?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n\nSELECT ?library ?document ?modified_at ?modified_by WHERE {\n  # Inputs: a library's name, and the start of the window (a week ago) as\n  # xsd:dateTime. UNDEF answers for every library or date.\n  VALUES (?library ?since) { (UNDEF UNDEF) }\n  ?l a/rdfs:subClassOf* c:library ;\n     rdfs:label ?library .\n  ?d a/rdfs:subClassOf* c:document ;\n     r:in_library ?l ;\n     rdfs:label ?document ;\n     p:modified_at ?modified_at .\n  FILTER(!BOUND(?since) || ?modified_at >= ?since)\n  OPTIONAL {\n    ?d r:modified_by ?u .\n    ?u a/rdfs:subClassOf* c:user ;\n       rdfs:label ?modified_by .\n  }\n}\nORDER BY ?library DESC(?modified_at)\n"),
        StarterQuestion(id="doc-03", text="Who created a document, and when?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?document ?created_at ?created_by WHERE {\n  # Input: a document's name. UNDEF answers for every document.\n  VALUES ?document { UNDEF }\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document .\n  OPTIONAL { ?d p:created_at ?created_at }\n  OPTIONAL {\n    ?d r:created_by ?u .\n    ?u a/rdfs:subClassOf* c:user ;\n       rdfs:label ?created_by .\n  }\n}\nORDER BY ?document\n"),
        StarterQuestion(id="doc-04", text="Which libraries and pages does a site hold?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?site ?kind ?item WHERE {\n  # Input: a site's name. UNDEF answers for every site.\n  VALUES ?site { UNDEF }\n  ?s a/rdfs:subClassOf* c:site ;\n     rdfs:label ?site .\n  ?x r:in_site ?s ;\n     rdfs:label ?item .\n  { ?x a/rdfs:subClassOf* c:library BIND(\"library\" AS ?kind) }\n  UNION\n  { ?x a/rdfs:subClassOf* c:page BIND(\"page\" AS ?kind) }\n}\nORDER BY ?site ?kind ?item\n"),
        StarterQuestion(id="doc-05", text="Where is a document: its folders up to its library and site?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?document ?path ?folder ?library ?site WHERE {\n  # Input: a document's name. UNDEF answers for every document.\n  VALUES ?document { UNDEF }\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document .\n  OPTIONAL { ?d p:path ?path }\n  # Every folder up the path: one or more IN_FOLDER steps.\n  OPTIONAL {\n    ?d r:in_folder+ ?f .\n    ?f a/rdfs:subClassOf* c:folder ;\n       rdfs:label ?folder .\n  }\n  OPTIONAL {\n    ?d r:in_library ?l .\n    ?l a/rdfs:subClassOf* c:library ;\n       rdfs:label ?library .\n    OPTIONAL {\n      ?l r:in_site ?s .\n      ?s a/rdfs:subClassOf* c:site ;\n         rdfs:label ?site .\n    }\n  }\n}\nORDER BY ?document ?folder\n"),
        StarterQuestion(id="doc-06", text="Which documents carry a tag, or a narrower tag?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?tag ?document ?tagged_with WHERE {\n  # Input: a tag's name. UNDEF answers for every tag.\n  VALUES ?tag { UNDEF }\n  ?t a/rdfs:subClassOf* c:tag ;\n     rdfs:label ?tag .\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document ;\n     r:tagged_with ?direct .\n  # The tag itself or a narrower one: zero or more BROADER steps.\n  ?direct r:broader* ?t ;\n          rdfs:label ?tagged_with .\n}\nORDER BY ?tag ?document\n"),
        StarterQuestion(id="doc-07", text="Which documents are of a given type, such as contracts or policies?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?document_type ?document WHERE {\n  # Input: a document type, such as Contract. UNDEF answers for every type.\n  VALUES ?document_type { UNDEF }\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document ;\n     p:document_type ?document_type .\n}\nORDER BY ?document_type ?document\n"),
        StarterQuestion(id="doc-08", text="Which documents may a given person or group read?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT DISTINCT ?document ?principal WHERE {\n  # Input: the principals of a person or a group as the source writes them:\n  # a user's own principal and those of its groups. UNDEF lists every reader.\n  VALUES ?principal { UNDEF }\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document ;\n     p:acl ?principal .\n}\nORDER BY ?document ?principal\n"),
        StarterQuestion(id="doc-09", text="Which documents link to a given document?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?target ?document WHERE {\n  # Input: the linked document's name. UNDEF answers for every document.\n  VALUES ?target { UNDEF }\n  ?t a/rdfs:subClassOf* c:document ;\n     rdfs:label ?target .\n  ?d a/rdfs:subClassOf* c:document ;\n     r:links_to ?t ;\n     rdfs:label ?document .\n}\nORDER BY ?target ?document\n"),
        StarterQuestion(id="doc-10", text="Which documents carry a sensitivity label, such as Confidential?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?sensitivity_label ?document WHERE {\n  # Input: a sensitivity label, such as Confidential. UNDEF answers for\n  # every label.\n  VALUES ?sensitivity_label { UNDEF }\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document ;\n     p:sensitivity_label ?sensitivity_label .\n}\nORDER BY ?sensitivity_label ?document\n"),
        StarterQuestion(id="doc-11", text="Which documents have the same content in more than one place?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?content_hash ?document ?path WHERE {\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document ;\n     p:content_hash ?content_hash .\n  OPTIONAL { ?d p:path ?path }\n  {\n    SELECT ?content_hash WHERE {\n      ?x a/rdfs:subClassOf* c:document ;\n         p:content_hash ?content_hash .\n    }\n    GROUP BY ?content_hash\n    HAVING (COUNT(?x) > 1)\n  }\n}\nORDER BY ?content_hash ?path\n"),
        StarterQuestion(id="doc-12", text="Which users changed the most documents in a library this month?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?library ?user (COUNT(?d) AS ?documents_changed) WHERE {\n  # Input: a library's name. UNDEF answers for every library.\n  VALUES ?library { UNDEF }\n  ?l a/rdfs:subClassOf* c:library ;\n     rdfs:label ?library .\n  ?d a/rdfs:subClassOf* c:document ;\n     r:in_library ?l ;\n     p:modified_at ?modified_at ;\n     r:modified_by ?u .\n  ?u a/rdfs:subClassOf* c:user ;\n     rdfs:label ?user .\n  # This month: the year and the month of today.\n  FILTER(YEAR(?modified_at) = YEAR(NOW()) && MONTH(?modified_at) = MONTH(NOW()))\n}\nGROUP BY ?library ?user\nORDER BY ?library DESC(?documents_changed) ?user\n"),
        StarterQuestion(id="doc-13", text="What file types does a library hold, by count and size?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?library ?file_extension ?mime_type (COUNT(?d) AS ?documents) (SUM(?size) AS ?size_bytes) WHERE {\n  ?d a/rdfs:subClassOf* c:document ;\n     r:in_library ?l ;\n     p:file_extension ?file_extension .\n  OPTIONAL { ?d p:mime_type ?mime_type }\n  OPTIONAL { ?d p:size_bytes ?size }\n  ?l a/rdfs:subClassOf* c:library ;\n     rdfs:label ?library .\n}\nGROUP BY ?library ?file_extension ?mime_type\nORDER BY ?library ?file_extension\n"),
        StarterQuestion(id="doc-14", text="Which documents are in a language, with how many pages?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?language ?document ?page_count WHERE {\n  # Input: a language as a BCP 47 tag, such as de. UNDEF answers for every\n  # language.\n  VALUES ?language { UNDEF }\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document ;\n     p:language ?language .\n  OPTIONAL { ?d p:page_count ?page_count }\n}\nORDER BY ?language ?document\n"),
        StarterQuestion(id="doc-15", text="Where does a document come from: which system, which id, which link, which version?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT ?document ?source_system ?source_id ?source_url ?version_label WHERE {\n  # Input: a document's name. UNDEF answers for every document.\n  VALUES ?document { UNDEF }\n  ?d a/rdfs:subClassOf* c:document ;\n     rdfs:label ?document ;\n     p:source_system ?source_system .\n  OPTIONAL { ?d p:source_id ?source_id }\n  OPTIONAL { ?d p:source_url ?source_url }\n  OPTIONAL { ?d p:version_label ?version_label }\n}\nORDER BY ?document\n"),
        StarterQuestion(id="doc-16", text="Which people wrote documents in a site, and who are they?", sparql="PREFIX c: <https://littlebigbrain.com/class/>\nPREFIX p: <https://littlebigbrain.com/p/>\nPREFIX r: <https://littlebigbrain.com/r/>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n\nSELECT DISTINCT ?site ?person ?email ?job_title WHERE {\n  # Input: a site's name. UNDEF answers for every site.\n  VALUES ?site { UNDEF }\n  ?s a/rdfs:subClassOf* c:site ;\n     rdfs:label ?site .\n  ?d a/rdfs:subClassOf* c:document ;\n     r:created_by ?x .\n  # A file is in a library of the site; a page is in the site.\n  { ?d r:in_library/r:in_site ?s } UNION { ?d r:in_site ?s }\n  ?x a/rdfs:subClassOf* c:person ;\n     rdfs:label ?person .\n  OPTIONAL { ?x p:email ?email }\n  OPTIONAL { ?x p:job_title ?job_title }\n}\nORDER BY ?site ?person\n"),
    )


